def do_algebra(operator, operand):
    # Initialize variables for carrying out the operation
    carry_out = False

    # Iterate through each element in the operand list
    for i in range(len(operand)):

        # Check if there's an operator present in the current position
        if operator[i] != '':

            # If there's an operator, perform the corresponding operation on the current operand
            if operator[i][0] == '+':
                operand[i] += int(operand[i+1])

            elif operator[i][0] == '-':
                operand[i] -= int(operand[i+1])

            elif operator[i][0] == '*':
                operand[i] *= int(operand[i+1])

            elif operator[i][0] == '//':
                operand[i] //= int(operand[i+1])

            elif operator[i][0] == '**':
                operand[i] **= int(operand[i+1])

            else:
                print("Invalid operator")
                break

            # Toggle the carry-out flag based on whether the current operand was carried over or not
            carry_out = True

        else:
            # If no operator is found, simply add the current operand to the next one
            operand.append(int(operand[i]))

    # Return the final result after performing all operations
    return sum(operand) if carry_out else operand[0]

