def encode(message):
    encoded_message = ''

    for char in message:
        if char.isalpha():
            if char.lower() == char.upper():
                # Swap case
                encoded_char = chr(ord(char) - 32)
            else:
                # Replace vowels with their next letter
                if char.lower() == 'a':
                    encoded_char = 'b'
                elif char.lower() == 'e':
                    encoded_char = 'f'
                elif char.lower() == 'i':
                    encoded_char = 'j'
                elif char.lower() == 'o':
                    encoded_char = 'p'
                elif char.lower() == 'u':
                    encoded_char = 'v'

                # Check if character is a vowel
                if char.lower() not in ['a', 'e', 'i', 'o', 'u']:
                    continue

                # Find position of next vowel
                pos = ord(encoded_char) - ord(char)
                if pos < 0 or pos > 1:
                    continue

                # Replace character with its next vowel
                encoded_char = chr(pos + 2)

        encoded_message += encoded_char

    return encoded_message

