def max_fill(grid: List[List[int]], capacity: int) -> int:
    # Initialize variables for counting and filling
    count = 0
    filled = 0

    # Iterate through each row and column in the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                # If there's water at the current position, fill the bucket
                if filled < capacity:
                    count += 1
                    filled += 1
                else:
                    # Otherwise, move to the next cell and refill the bucket
                    while filled < capacity:
                        if grid[i+1][j] != 1:
                            break
                        else:
                            filled += 1
                            count += 1
                            if filled >= capacity:
                                return count

    return count

